111	template <typename T>
112	ol_result_t printPlatformValue(std::ostream &S, ol_platform_handle_t Plat,
113	                               ol_platform_info_t Info, const char *Desc) {
114	  S << Desc << ": ";
115	
116	  if constexpr (std::is_pointer_v<T>) {
117	    std::vector<uint8_t> Val;
118	    size_t Size;
119	    OFFLOAD_ERR(olGetPlatformInfoSize(Plat, Info, &Size));
120	    Val.resize(Size);
121	    OFFLOAD_ERR(olGetPlatformInfo(Plat, Info, sizeof(Val), Val.data()));
122	    doWrite(S, reinterpret_cast<T>(Val.data()));
123	  } else {
124	    T Val;
125	    OFFLOAD_ERR(olGetPlatformInfo(Plat, Info, sizeof(Val), &Val));
126	    doWrite(S, std::move(Val));
127	  }
128	  S << "\n";
129	  return OL_SUCCESS;
130	}
