258	
259	ol_result_t printRoot(std::ostream &S) {
260	  OFFLOAD_ERR(olInit(nullptr));
261	  S << "Liboffload Version: " << OL_VERSION_MAJOR << "." << OL_VERSION_MINOR
262	    << "." << OL_VERSION_PATCH << "\n";
263	
264	  std::vector<ol_device_handle_t> Devices;
265	  OFFLOAD_ERR(olIterateDevices(
266	      [](ol_device_handle_t Device, void *UserData) {
267	        reinterpret_cast<decltype(Devices) *>(UserData)->push_back(Device);
268	        return true;
269	      },
270	      &Devices));
271	
272	  S << "Num Devices: " << Devices.size() << "\n";
273	
274	  for (auto &D : Devices) {
275	    S << "\n";
276	    OFFLOAD_ERR(printDevice(S, D));
277	  }
278	
279	  OFFLOAD_ERR(olShutDown());
280	  return OL_SUCCESS;
281	}
282	
283	int main(int argc, char **argv) {
284	  auto Err = printRoot(std::cout);
285	
286	  if (Err) {
287	    std::cerr << "[Liboffload error " << Err->Code << "]: " << Err->Details
288	              << "\n";
289	    return 1;
290	  }
291	  return 0;
292	}
