162	/// A raw_ostream that tracks `\n` and print the prefix after each
163	/// newline. Based on raw_ldbg_ostream from Support/DebugLog.h
164	class LLVM_ABI odbg_ostream final : public raw_ostream {
165	public:
166	  enum IfLevel : uint32_t;
167	  enum OnlyLevel : uint32_t;
168	
169	private:
170	  std::string Prefix;
171	  raw_ostream &Os;
172	  uint32_t BaseLevel;
173	  bool ShouldPrefixNextString;
174	  bool ShouldEmitNewLineOnDestruction;
175	  bool NeedEndNewLine = false;
176	
177	  /// Buffer to reduce interference between different threads
178	  /// writing at the same time to the underlying stream.
179	  static constexpr size_t BufferSize = 256;
180	  llvm::SmallString<BufferSize> Buffer;
181	
182	  // Stream to write into Buffer. Its flushed to Os upon destruction.
183	  llvm::raw_svector_ostream BufferStrm;
184	
185	  /// If the stream is muted, writes to it are ignored
186	  bool Muted = false;
187	
188	  /// Split the line on newlines and insert the prefix before each
189	  /// newline. Forward everything to the underlying stream.
190	  void write_impl(const char *Ptr, size_t Size) final {
191	    if (Muted)
192	      return;
193	
194	    NeedEndNewLine = false;
195	    auto Str = StringRef(Ptr, Size);
196	    auto Eol = Str.find('\n');
197	    // Handle `\n` occurring in the string, ensure to print the prefix at the
198	    // beginning of each line.
199	    while (Eol != StringRef::npos) {
200	      // Take the line up to the newline (including the newline).
201	      StringRef Line = Str.take_front(Eol + 1);
202	      if (!Line.empty())
203	        writeWithPrefix(Line);
204	      // We printed a newline, record here to print a prefix.
205	      ShouldPrefixNextString = true;
206	      Str = Str.drop_front(Eol + 1);
207	      Eol = Str.find('\n');
208	    }
209	    if (!Str.empty()) {
210	      writeWithPrefix(Str);
211	      NeedEndNewLine = true;
212	    }
213	  }
214	  void emitPrefix() { BufferStrm.write(Prefix.c_str(), Prefix.size()); }
215	  void writeWithPrefix(StringRef Str) {
216	    if (ShouldPrefixNextString) {
217	      emitPrefix();
218	      ShouldPrefixNextString = false;
219	    }
220	    BufferStrm.write(Str.data(), Str.size());
221	  }
222	
223	public:
224	  explicit odbg_ostream(std::string Prefix, raw_ostream &Os, uint32_t BaseLevel,
225	                        bool ShouldPrefixNextString = true,
226	                        bool ShouldEmitNewLineOnDestruction = true)
227	      : Prefix(std::move(Prefix)), Os(Os), BaseLevel(BaseLevel),
228	        ShouldPrefixNextString(ShouldPrefixNextString),
229	        ShouldEmitNewLineOnDestruction(ShouldEmitNewLineOnDestruction),
230	        BufferStrm(Buffer) {
231	    SetUnbuffered();
232	  }
233	  ~odbg_ostream() final {
234	    if (ShouldEmitNewLineOnDestruction && NeedEndNewLine)
235	      BufferStrm << '\n';
236	    Os << BufferStrm.str();
237	  }
238	  odbg_ostream(const odbg_ostream &) = delete;
239	  odbg_ostream &operator=(const odbg_ostream &) = delete;
240	  odbg_ostream(odbg_ostream &&other) : Os(other.Os), BufferStrm(Buffer) {
241	    Prefix = std::move(other.Prefix);
242	    BaseLevel = other.BaseLevel;
243	    ShouldPrefixNextString = other.ShouldPrefixNextString;
244	    ShouldEmitNewLineOnDestruction = other.ShouldEmitNewLineOnDestruction;
245	    NeedEndNewLine = other.NeedEndNewLine;
246	    Muted = other.Muted;
247	    BufferStrm << other.BufferStrm.str();
248	  }
249	
250	  /// Forward the current_pos method to the underlying stream.
251	  uint64_t current_pos() const final { return BufferStrm.tell(); }
252	
253	  /// Some of the `<<` operators expect an lvalue, so we trick the type
254	  /// system.
255	  odbg_ostream &asLvalue() { return *this; }
256	
257	  void shouldMute(const IfLevel Filter) { Muted = Filter > BaseLevel; }
258	  void shouldMute(const OnlyLevel Filter) { Muted = BaseLevel != Filter; }
259	};
