271	struct DebugSettings {
272	  bool Enabled = false;
273	  uint32_t DefaultLevel = 1;
274	  // Types/Components in this list are not printed when debug is enabled
275	  // unless they are explicitly requested by the user in IncludeFilters.
276	  llvm::SmallVector<StringRef> ExcludeFilters;
277	  // Types/Components in this list are printed when debug is enabled if
278	  // the debug level is equal or higher than the specified level.
279	  llvm::SmallVector<DebugFilter> IncludeFilters;
280	};
281	
282	[[maybe_unused]] static DebugFilter parseDebugFilter(StringRef Filter) {
283	  size_t Pos = Filter.find(':');
284	  if (Pos == StringRef::npos)
285	    return {Filter, 1};
286	
287	  StringRef Type = Filter.slice(0, Pos);
288	  uint32_t Level = 1;
289	  if (Filter.slice(Pos + 1, Filter.size()).getAsInteger(10, Level))
290	    Level = 1;
291	
292	  return {Type, Level};
293	}
294	
295	[[maybe_unused]] static DebugSettings &getDebugSettings() {
296	  static DebugSettings Settings;
297	  static std::once_flag Flag{};
298	  std::call_once(Flag, []() {
299	    // Eventually, we probably should allow the upper layers to set
300	    // debug settings directly according to their own env var or
301	    // other methods.
302	    // For now, mantain compatibility with existing libomptarget env var
303	    // and add a liboffload independent one.
304	    char *Env = getenv("LIBOMPTARGET_DEBUG");
305	    if (!Env) {
306	      Env = getenv("LIBOFFLOAD_DEBUG");
307	      if (!Env)
308	        return;
309	    }
310	
311	    StringRef EnvRef(Env);
312	    if (EnvRef == "0")
313	      return;
314	
315	    Settings.Enabled = true;
316	
317	    // Messages with Type/Components added to the exclude list are not
318	    // not printed when debug is enabled unless they are explicitly
319	    // requested by the user.
320	    // Eventually, this should be configured from the upper layers but
321	    // for now we can hardcode some excluded types here like:
322	    // Settings.ExcludeFilters.push_back(Type);
323	
324	    if (!EnvRef.getAsInteger(10, Settings.DefaultLevel))
325	      return;
326	
327	    Settings.DefaultLevel = 1;
328	
329	    for (auto &FilterSpec : llvm::split(EnvRef, ',')) {
330	      if (FilterSpec.empty())
331	        continue;
332	      DebugFilter Filter = parseDebugFilter(FilterSpec);
333	
334	      // Remove from ExcludeFilters if present
335	      Settings.ExcludeFilters.erase(
336	          std::remove_if(Settings.ExcludeFilters.begin(),
337	                         Settings.ExcludeFilters.end(),
338	                         [&](StringRef OutType) {
339	                           return OutType.equals_insensitive(Filter.Type);
340	                         }),
341	          Settings.ExcludeFilters.end());
342	
343	      Settings.IncludeFilters.push_back(Filter);
344	    }
345	  });
346	
347	  return Settings;
348	}
349	
350	inline bool isDebugEnabled() { return getDebugSettings().Enabled; }
351	
352	[[maybe_unused]] static bool
353	shouldPrintDebug(const char *Component, const char *Type, uint32_t &Level) {
354	  const auto &Settings = getDebugSettings();
355	  if (!Settings.Enabled)
356	    return false;
357	
358	  for (const auto &Filter : Settings.ExcludeFilters) {
359	    if (Filter.equals_insensitive(Type) || Filter.equals_insensitive(Component))
360	      return false;
361	  }
362	
363	  if (Settings.IncludeFilters.empty()) {
364	    if (Level <= Settings.DefaultLevel) {
365	      Level = Settings.DefaultLevel;
366	      return true;
367	    }
368	    return false;
369	  }
370	
371	  for (const auto &DT : Settings.IncludeFilters) {
372	    if (DT.Level < Level)
373	      continue;
374	    if (DT.Type.equals_insensitive("all") || DT.Type.equals_insensitive(Type) ||
375	        DT.Type.equals_insensitive(Component)) {
376	      Level = DT.Level;
377	      return true;
378	    }
379	  }
380	
381	  return false;
382	}
